def shipping_fee(subtotal_cents):
    if subtotal_cents < 0:
        raise ValueError("subtotal must be nonnegative")
    return 0 if subtotal_cents >= 5000 else 500

import unittest
from shipping import shipping_fee


class ShippingTests(unittest.TestCase):
    def test_tautology(self):
        actual = shipping_fee(5000)
        self.assertEqual(actual, actual)

    def test_vacuous(self):
        eligible_subtotals = []
        self.assertTrue(all(shipping_fee(n) == 0 for n in eligible_subtotals))

    def test_unreachable(self):
        shipping_fee(5000)
        return
        self.assertEqual(shipping_fee(5000), 0)
